import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.vLhlLNVn.js";const y=JSON.parse('{"title":"Periods, updates and time","description":"","frontmatter":{"order":3,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/05.hintergrund/03.perioden-und-zeit.md"},"headers":[],"relativePath":"adapter/sourceanalytix/hintergrund/perioden-und-zeit.md","filePath":"adapter/sourceanalytix/hintergrund/perioden-und-zeit.md","lastUpdated":null}'),n={name:"adapter/sourceanalytix/hintergrund/perioden-und-zeit.md"};function s(d,e,i,h,u,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="periods-updates-and-time" tabindex="-1">Periods, updates and time <a class="header-anchor" href="#periods-updates-and-time" aria-label="Permalink to &quot;Periods, updates and time&quot;">​</a></h1><p><a id="values-updated-live-midnight"></a></p><h2 id="when-are-values-updated-live-or-at-midnight" tabindex="-1">When are values updated: live or at midnight? <a class="header-anchor" href="#when-are-values-updated-live-or-at-midnight" aria-label="Permalink to &quot;When are values updated: live or at midnight?&quot;">​</a></h2><p><strong>In short:</strong> Both. SourceAnalytix recalculates the running values immediately with every new value from the source. At midnight, the period rollover comes on top: it writes the previous periods such as &quot;yesterday&quot;, sets new start values and starts the new periods at 0.</p><h3 id="what-is-written-when" tabindex="-1">What is written when <a class="header-anchor" href="#what-is-written-when" aria-label="Permalink to &quot;What is written when&quot;">​</a></h3><table tabindex="0"><thead><tr><th>States</th><th>When</th></tr></thead><tbody><tr><td><code>cumulativeReading</code>, and the values <code>01_currentDay</code> to <code>05_currentYear</code> under <code>currentYear.&lt;category&gt;</code></td><td>With every new value from the source, but only if the value changes</td></tr><tr><td><code>currentWeek.&lt;weekday&gt;</code>, <code>weeks</code>, <code>months</code>, <code>quarters</code> of the running period, and the yearly archive</td><td>Likewise with every new value</td></tr><tr><td><code>statisticsJson</code></td><td>Collected shortly after the changes, at most every 300 ms</td></tr><tr><td><code>01_previousDay</code> to <code>05_previousYear</code></td><td>At the rollover of the respective period, with the time stamp 23:59:59 on the last day of the period</td></tr><tr><td>Start values in the source settings</td><td>At the rollover of the respective period</td></tr></tbody></table><p>SourceAnalytix writes all values as acknowledged (<code>ack=true</code>). Because the running values are only written when they change, their time stamp shows the last change. If the source doesn&#39;t deliver a new value for a while, the SourceAnalytix values stay as they are, too.</p><p>For power sources (W), SourceAnalytix calculates the energy since the last value with every new power value. So here, too, the values only change when the device reports something.</p><h3 id="the-rollover-at-midnight" tabindex="-1">The rollover at midnight <a class="header-anchor" href="#the-rollover-at-midnight" aria-label="Permalink to &quot;The rollover at midnight&quot;">​</a></h3><p>At 0:00 system time, SourceAnalytix checks which periods have ended: the day always, the week on Monday, the month on the 1st, the quarter on 1 January, April, July and October, the year on 1 January. For each period that has ended, it copies the running value into the previous period and sets the start value to the current total. The new period then starts at 0.</p><p>On Monday, SourceAnalytix also clears the weekdays of the running week, and on 1 January the weeks, months and quarters under <code>currentYear</code>.</p><p>During the rollover, calculation pauses briefly. Values that arrive at that moment are not processed. A change is planned (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1270" target="_blank" rel="noreferrer">#1270</a>).</p><p>If ioBroker was off at midnight, SourceAnalytix catches up on the rollover at startup, and it also checks every hour. See <a href="./../anleitungen/betrieb-und-wartung#iobroker-was-down-midnight-recover">ioBroker was off at midnight</a>.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Where do I find yesterday, last week, last month (previous states)?</a> · <a href="#week-month-quarter-year-values">Why do week, month, quarter and year values differ?</a> · <a href="./../fehlerbehebung/log-meldungen#midnight-crash-rollover-wrong-time">Crash or rollover at the wrong time</a></p><p><a id="week-52-53-have-values"></a></p><h2 id="why-does-week-52-53-show-values-in-the-new-year" tabindex="-1">Why does week 52/53 show values in the new year? <a class="header-anchor" href="#why-does-week-52-53-show-values-in-the-new-year" aria-label="Permalink to &quot;Why does week 52/53 show values in the new year?&quot;">​</a></h2><p><strong>In short:</strong> SourceAnalytix counts calendar weeks according to ISO 8601. A week starts on Monday, and week 1 is the week with the first Thursday of the year. The first days of January can therefore still belong to week 52 or 53 of the previous year, and the last days of December can already belong to week 1 of the next year.</p><p>Two examples:</p><table tabindex="0"><thead><tr><th>Days</th><th>Calendar week</th></tr></thead><tbody><tr><td>Monday, 29 December 2025, to Sunday, 4 January 2026</td><td>Week 1 of 2026</td></tr><tr><td>Monday, 28 December 2026, to Sunday, 3 January 2027</td><td>Week 53 of 2026</td></tr></tbody></table><h3 id="how-sourceanalytix-handles-this" tabindex="-1">How SourceAnalytix handles this <a class="header-anchor" href="#how-sourceanalytix-handles-this" aria-label="Permalink to &quot;How SourceAnalytix handles this&quot;">​</a></h3><p><strong>From v0.6.2:</strong> SourceAnalytix assigns each week to the year it belongs to under ISO 8601 (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1256" target="_blank" rel="noreferrer">#1256</a>). In detail:</p><ul><li><strong><code>02_currentWeek</code></strong> always counts the whole week from Monday to Sunday, even across the turn of the year. On 2 January 2027, it therefore contains the consumption since Monday, 28 December. <code>05_currentYear</code>, on the other hand, starts at 0 on 1 January.</li><li><strong><code>currentYear.&lt;category&gt;.weeks</code></strong> only shows weeks that belong to the current calendar year. From 1 to 3 January 2027, SourceAnalytix writes nothing there, because week 53 belongs to 2026. Likewise, on 29 to 31 December 2025 it doesn&#39;t write to week <code>01</code>, so that the first week of January of the current year isn&#39;t overwritten.</li><li><strong>The week archive</strong> <code>&lt;year&gt;.&lt;category&gt;.weeks</code> is in the folder of the year the week belongs to. Week 53 of 2026 is under <code>2026.consumed.weeks.53</code>, including the January days of 2027. Week 1 of 2026 is under <code>2026.consumed.weeks.01</code>, including the December days of 2025.</li></ul><p><strong>Up to v0.6.1:</strong> SourceAnalytix used the ISO number for weeks but the calendar year. In early January, the values of week 52 or 53 therefore ended up under <code>currentYear</code> and in the archive folder of the new year. At the end of December, week 1 of the next year overwrote the first week of January in the archive of the current year.</p><p><strong>See also:</strong> <a href="#week-month-quarter-year-values">Why do week, month, quarter and year values differ?</a> · <a href="./../referenz/states-und-meldungen#week-month-quarter-states-weekdays">Which week, month and quarter states and weekdays are there?</a> · <a href="./../referenz/states-und-meldungen#happens-turn-year">What happens at the turn of the year?</a></p><p><a id="sourceanalytix-calculate-retroactively-only-activation"></a></p><h2 id="does-sourceanalytix-calculate-retroactively-or-only-from-activation" tabindex="-1">Does SourceAnalytix calculate retroactively or only from activation? <a class="header-anchor" href="#does-sourceanalytix-calculate-retroactively-or-only-from-activation" aria-label="Permalink to &quot;Does SourceAnalytix calculate retroactively or only from activation?&quot;">​</a></h2><p><strong>In short:</strong> Only from activation. SourceAnalytix doesn&#39;t recalculate values from the past. If you know the meter readings at the beginning of the running periods, you can enter them as start values. Consumption since the beginning of the day, week, month, quarter or year then counts too, but only for the running periods.</p><h3 id="what-happens-on-first-activation" tabindex="-1">What happens on first activation <a class="header-anchor" href="#what-happens-on-first-activation" aria-label="Permalink to &quot;What happens on first activation&quot;">​</a></h3><p>With the first value of a new source, SourceAnalytix sets every empty start value and every start value of 0 to the current total. All periods therefore start at 0. The log says &quot;Initialized empty period start values for … from current reading …&quot;. Start values you entered stay as they are.</p><p>From v0.7.0, the &quot;Add source&quot; wizard asks about this in the &quot;Start values&quot; step:</p><table tabindex="0"><thead><tr><th>Choice</th><th>What happens</th></tr></thead><tbody><tr><td>&quot;Count from now&quot;</td><td>All periods start at 0 now.</td></tr><tr><td>&quot;Include consumption since the start of the period&quot;</td><td>You enter the meter readings at the beginning of the day, week, month, quarter and year. Empty fields start from now.</td></tr></tbody></table><p>What exactly belongs in the fields is described under <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values (and in which unit)?</a>.</p><h3 id="what-applies-afterwards" tabindex="-1">What applies afterwards <a class="header-anchor" href="#what-applies-afterwards" aria-label="Permalink to &quot;What applies afterwards&quot;">​</a></h3><ul><li>The first month, the first quarter and the first year only contain the consumption since activation, unless you entered start values.</li><li>The previous periods such as <code>01_previousDay</code> or <code>03_previousMonth</code> are only filled after the first rollover of the respective period.</li><li>SourceAnalytix can&#39;t create values for earlier periods, such as last year. Start values only take effect until the end of the running period.</li></ul><p>Power sources (W) always count from activation. They don&#39;t deliver a meter reading, and SourceAnalytix only builds their total itself from activation on. The wizard therefore doesn&#39;t offer &quot;Include consumption since the start of the period&quot; for them.</p><p>Adding older consumption or meter readings afterwards is planned (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/256" target="_blank" rel="noreferrer">#256</a>).</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values (and in which unit)?</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#values-negative-after-entering-start">Why are my values negative after I entered start values?</a></p><p><a id="week-month-quarter-year-values"></a></p><h2 id="why-do-week-month-quarter-and-year-values-differ" tabindex="-1">Why do week, month, quarter and year values differ? <a class="header-anchor" href="#why-do-week-month-quarter-and-year-values-differ" aria-label="Permalink to &quot;Why do week, month, quarter and year values differ?&quot;">​</a></h2><p><strong>In short:</strong> Each period has its own start value and begins at a different time. Consumption is always the total minus the start value of that period. Because a week begins on Monday and can span month or year boundaries, weekly values don&#39;t match monthly or yearly values, and the sum of the weeks doesn&#39;t add up to the month.</p><h3 id="when-each-period-begins" tabindex="-1">When each period begins <a class="header-anchor" href="#when-each-period-begins" aria-label="Permalink to &quot;When each period begins&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Period</th><th>State under <code>currentYear.&lt;category&gt;</code></th><th>Begins at 0:00 on</th></tr></thead><tbody><tr><td>Day</td><td><code>01_currentDay</code></td><td>Every day</td></tr><tr><td>Week</td><td><code>02_currentWeek</code></td><td>Monday</td></tr><tr><td>Month</td><td><code>03_currentMonth</code></td><td>The 1st of the month</td></tr><tr><td>Quarter</td><td><code>04_currentQuarter</code></td><td>1 January, 1 April, 1 July, 1 October</td></tr><tr><td>Year</td><td><code>05_currentYear</code></td><td>1 January</td></tr></tbody></table><p>At the rollover, SourceAnalytix sets the start value of each period that has ended to the total at that moment. The other periods carry on untouched.</p><h3 id="why-the-values-don-t-add-up" tabindex="-1">Why the values don&#39;t add up <a class="header-anchor" href="#why-the-values-don-t-add-up" aria-label="Permalink to &quot;Why the values don&#39;t add up&quot;">​</a></h3><ul><li><strong>A week across a month boundary:</strong> On Saturday, 3 October 2026, <code>03_currentMonth</code> counts three days but <code>02_currentWeek</code> counts five, because the week began on Monday, 28 September. It therefore contains days that belong to the previous month. The same applies at the turn of the year, see <a href="#week-52-53-have-values">Week 52/53</a>.</li><li><strong>Activation in the middle of a period:</strong> Without start values of your own, all periods begin at activation. The first month, the first quarter and the first year then contain the same amount, namely the consumption since activation.</li><li><strong>Your own start values:</strong> If you entered start values, each period counts from its own value. If the values don&#39;t fit together, the results don&#39;t fit together either.</li><li><strong>Rounding:</strong> SourceAnalytix rounds each period value on its own. The sum of rounded daily values can therefore differ from the monthly value in the last digit.</li></ul><p>For costs, the basic fee comes on top: it is booked monthly and not spread evenly over the days. More on this under <a href="./../anleitungen/preise-und-kosten#include-monthly-base-fee">How do I include a monthly basic fee?</a>.</p><h3 id="where-the-individual-weeks-and-months-are" tabindex="-1">Where the individual weeks and months are <a class="header-anchor" href="#where-the-individual-weeks-and-months-are" aria-label="Permalink to &quot;Where the individual weeks and months are&quot;">​</a></h3><p>You find the individual weeks, months and quarters of the current year under <code>currentYear.&lt;category&gt;.weeks.01</code> to <code>53</code>, <code>months.01_January</code> to <code>12_December</code> and <code>quarters.Q1</code> to <code>Q4</code>, if &quot;Weeks&quot;, &quot;Months&quot; and &quot;Quarters&quot; are switched on under &quot;Current year&quot; in the instance settings. February, for example, is in <code>months.02_February</code>.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values (and in which unit)?</a> · <a href="./../referenz/states-und-meldungen#week-month-quarter-states-weekdays">Which week, month and quarter states and weekdays are there?</a> · <a href="#values-updated-live-midnight">When are values updated: live or at midnight?</a></p>',49)])])}const p=t(n,[["render",s]]);export{y as __pageData,p as default};
